import React from 'react';
import { TouchableOpacity, Text, StyleSheet, ViewStyle, TextStyle } from 'react-native';

type CustomButtonProps = {
  title: string;
  onPress: () => void;
  style?: ViewStyle;
  textStyle?: TextStyle;
};

export const CustomButton = ({ title, onPress, style, textStyle }: CustomButtonProps) => {
  return (
    <TouchableOpacity style={[styles.button, style]} onPress={onPress}>
      <Text style={[styles.text, textStyle]}>{title}</Text>
    </TouchableOpacity>
  );
};

const styles = StyleSheet.create({
  button: { backgroundColor: '#007AFF', padding: 12, borderRadius: 8, alignItems: 'center' },
  text: { color: '#FFFFFF', fontSize: 16, fontWeight: 'bold' },
});

import React from 'react';
import { View, Text, Image, StyleSheet } from 'react-native';

type ProductCardProps = {
  title: string;
  price: number;
  imageUrl: string;
  description: string;
};

export const ProductCard = ({ title, price, imageUrl, description }: ProductCardProps) => {
  return (
    <View style={styles.card}>
      <Image source={{ uri: imageUrl }} style={styles.image} />
      <Text style={styles.title}>{title}</Text>
      <Text style={styles.price}>${price.toFixed(2)}</Text>
      <Text style={styles.desc}>{description}</Text>
    </View>
  );
};

const styles = StyleSheet.create({
  card: { padding: 16, borderRadius: 10, backgroundColor: '#fff', marginVertical: 8 },
  image: { width: '100%', height: 150, borderRadius: 8 },
  title: { fontSize: 18, fontWeight: 'bold', marginTop: 8 },
  price: { fontSize: 16, color: '#0a7', marginVertical: 4 },
  desc: { fontSize: 14, color: '#666' },
});
